########################################################################
## Read Seurat clusters to look at cell-types based on a custom marker gene list (Fast cluster exploration)
## INPUT:
##      1) A custom Gene-marker list.
##      2) DGE list generated by Seurat
## 
## OUPUT:
##      1) A csv files with the matched markers found in each cluster. 
##
## Authors. CSC 
## Date. Feb 27th, 2024 / last md. Feb 28th
########################################################################

# load libraries
library(tidyverse)
library(dplyr)
library(data.table)
library(magrittr)

library(here)

here::here()

# Check if processed_data directory exists, if not create it
if (!dir.exists(here("processed-data/04_DiffExpr_Clustering_seurat/"))) {
    dir.create(here("processed-data/04_DiffExpr_Clustering_seurat/"))
}

# contains the different marker list 
source(here("code/functions_custom", "remote_DGE_marker_gene_lists.R"))       # Call functions to read paths

get_seurat <- function(name) {
    
    #Ex. /dcs04/lieber/lcolladotor/Habenula_R01_LIBD4270/Hb_multiome/processed-data/02_merge_seurats/seurat.combined.data_counts_PCA.rds
    sobj <- readRDS(name)
    # verification of the integration
    print(table(sobj$orig.ident))
    # S1_Hb_KDM S2_Hb_KDM
    # 8178      9816
    print(head(sobj, n=2))
    return(sobj)
    
}

#############################           Initials        ################################
############################# Pickup a Marker gene list ################################

# We have access to 3 gene markers lists:

# Erik and Top50r putative marker genes merged
markers.custom <- get_erik_and_Hb_markers_genes()          # merged lists
prefix_name <- 'all_gm'                                    # prefix to save matched markers found in the clusters
#markers.custom <- get_bukola_markers_genes_Hb()           # Bukola lists
#prefix_name <- 'erik_gm'  
#markers.custom <- get_Top50r_markers_genes_Hb()           # Top50r lists (putative Hb)
#prefix_name <- 'Top50r_gm'  

# str(markers.custom)
